#include "gfx.h"
#include "../platform/mmio.h"
#include "../platform/platform.h"
#include "../cores/gfx_touch_core.h"
#define caps_dbuf (caps.dbuf)
#include "../generated/font_data.h"         /* generated by tools/gen_font_atlases.py: FONT_GLYPHS and the advances of the power-up font */

#define OP_RECT 1u
#define OP_CHAR 2u
#define OP_BAR 5u

static gt_t gfx_touch = { 0xFFFFu, 0, 0xFFFFu, 0 };                      /* the rows the commands since gfx_touch_reset() wrote (cores/gfx_touch_core.h) */
void gfx_touch_reset(void) { gt_reset(&gfx_touch); }
uint32_t gfx_touch_rows(void) { return gt_visible(&gfx_touch) ? ((uint32_t)gfx_touch.y0 << 16) | gfx_touch.y1 : 0u; }
uint32_t gfx_cmds;                                         /* engine commands issued since boot (every R_FB_GO write): the host's per-meter command budget reads the difference around a tick */
#define FB_GO(v) do { gfx_cmds++; REG_WR(R_FB_GO, (v)); } while (0)
static uint32_t color_shadow = 0xFFFFFFFFu;
static inline void wait_fifo(void) { while (REG_RD(R_FB_GO) & 1u) { } }
static void set_colors(uint16_t fg, uint16_t bg)
{
    uint32_t v = ((uint32_t)bg << 16) | fg;
    if (v != color_shadow) { color_shadow = v; REG_WR(R_FB_COLOR, v); }
}

static void rect_raw(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t color)
{
    gt_note(&gfx_touch, y, h);
    wait_fifo();
    REG_WR(R_FB_ADDR, y * GFX_STRIDE + x);
    REG_WR(R_FB_SIZE, (h << 9) | w);
    set_colors(color, color);
    FB_GO(OP_RECT);
}
void gfx_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t color)
{
    if (!w || !h || x >= GFX_W || y >= GFX_H) return;
    if (x + w > GFX_W) w = GFX_W - x;
    if (y + h > GFX_H) h = GFX_H - y;
    rect_raw(x, y, w, h, color);
}
void gfx_bar(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t lit, uint16_t fg, uint16_t bg)       /* OP_BAR: the bottom `lit` rows in fg, the rest in bg, one command (the field is 9 bits wide in the bitstream) */
{
    if (!w || !h || x >= GFX_W || y >= GFX_H) return;
    if (x + w > GFX_W) w = GFX_W - x;
    if (y + h > GFX_H) h = GFX_H - y;
    if (lit > 511u) lit = 511u;
    gt_note(&gfx_touch, y, h);
    wait_fifo();
    REG_WR(R_FB_ADDR, y * GFX_STRIDE + x);
    REG_WR(R_FB_SIZE, (h << 9) | w);
    set_colors(fg, bg);
    FB_GO(OP_BAR | ((lit & 0x7Fu) << 3) | (((lit >> 7) & 0x3u) << 15));       /* the lit count: cmd_glyph (7 bits) and cmd_glyph_hi (2 bits) */
}
void gfx_rect_stash(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t color) { if (w && h) rect_raw(x, y, w, h, color); }      /* the off-screen stash (rows 360.., columns 400..): not clipped to the screen */


/* Text is Latin-1, one byte per character (docs/features/FONT_SPEC.md 3.6). The font memory holds U+0020..U+007E and U+00A0..U+00FF (191 glyphs; the engine takes the code as 8 bits, bit 7 on R_FB_GO bit 15);
 * every other code (controls, 0x7F..0x9F) draws as a space. The advance of each glyph is in font_adv_cur, which belongs to the font in the memory: the power-up font's table until fw2/gfx/font.c loads another. */
uint8_t font_adv_cur[FONT_GLYPHS] = FONT_DEFAULT_ADV;
static uint32_t glyph_of(char ch)
{
    const uint32_t c = (unsigned char)ch;
    return ((c >= 0x20u && c <= 0x7Eu) || c >= 0xA0u) ? c : (uint32_t)' ';
}
static inline uint32_t adv_of(uint32_t g) { return font_adv_cur[g < 0x80u ? g - 0x20u : g - 0xA0u + 95u]; }

/* One glyph at (x, y) in the off-screen stash (rows 360 and below, where gfx_text refuses to draw): the font self-test of the Check page reads the pixels back through the mailbox. g is the Latin-1 code. */
void gfx_char_stash(uint32_t x, uint32_t y, uint32_t g, uint16_t fg, uint16_t bg)
{
    set_colors(fg, bg);
    wait_fifo();
    REG_WR(R_FB_ADDR, y * GFX_STRIDE + x);
    FB_GO(OP_CHAR | ((g & 0x7Fu) << 3) | ((g >> 7) << 15));
}
uint32_t gfx_text_width(const char *s)
{
    uint32_t w = 0;
    for (; *s; s++) w += adv_of(glyph_of(*s));
    return w;
}

uint32_t gfx_text(uint32_t x, uint32_t y, const char *s, uint16_t fg, uint16_t bg)
{
    if (y + GFX_CELL_H > GFX_H) return x;
    gt_note(&gfx_touch, y, GFX_CELL_H);
    set_colors(fg, bg);
    for (; *s; s++) {
        uint32_t g = glyph_of(*s);
        if (x + 16u > GFX_W) break;      /* a cell past column 400 lands in the next scanline's memory: never draw one */
        wait_fifo();
        REG_WR(R_FB_ADDR, y * GFX_STRIDE + x);
        FB_GO(OP_CHAR | ((g & 0x7Fu) << 3) | ((g >> 7) << 15));       /* scale 1x: sx = sy = 0; glyph bit 7 rides on bit 15 (cmd_glyph_hi) */
        x += adv_of(g);
    }
    return x;
}

#define R_CLUT_IDX_A  0x800000C8u
#define R_CLUT_DATA_A 0x800000CCu
#define R_SDR_RDATA_A 0x80000080u
#define OP_BLIT 4u
#define OP_SBLIT 6u
#define OP_CBLIT 7u
#define DBUF_BASE1_W 1048576u                /* buffer 1 sits 2 MiB above buffer 0 (mp3_fb.sv DBUF_BASE1); only the visible 360 rows are doubled, the stash rows below are shared */
static int mb_wait(uint32_t t)
{
    while ((uint32_t)(cycles() - t) < 128u) { }
    while (REG_RD(R_SDR_STATUS) & 1u) if ((uint32_t)(cycles() - t) > CLK_HZ / 4u) return -1;
    return 0;
}
int gfx_mb_write(uint32_t a, uint32_t d) { REG_WR(R_SDR_ADDR, a); REG_WR(R_SDR_DATA, d); REG_WR(R_SDR_CTRL, 0x3Fu); return mb_wait(cycles()); }
int gfx_mb_read(uint32_t a, uint32_t *o) { REG_WR(R_SDR_ADDR, a); REG_WR(R_SDR_CTRL, 0x3Du); if (mb_wait(cycles())) return -1; *o = REG_RD(R_SDR_RDATA_A); return 0; }
void gfx_fence(void)
{
    const uint32_t a = 1021u * GFX_STRIDE + GFX_CELL_X;
    uint32_t r = 0;
    if (gfx_mb_write(a, 0xDEADBEEFu)) return;
    rect_raw(GFX_CELL_X, 1021u, 1u, 1u, 0x0001u);        /* the engine runs in order: when this lands, everything before it has (a stash row: shared by both buffers) */
    const uint32_t t0 = cycles();
    do { uint32_t t = cycles(); while ((uint32_t)(cycles() - t) < 256u) { } if (gfx_mb_read(a, &r)) return; } while (r == 0xDEADBEEFu && (uint32_t)(cycles() - t0) < CLK_HZ / 20u);
}
void gfx_clut_begin(uint32_t start) { wait_fifo(); gfx_fence(); REG_WR(R_CLUT_IDX_A, start); }
void gfx_clut_put(uint16_t v) { REG_WR(R_CLUT_DATA_A, v); }
void gfx_clut_load(uint32_t start, const uint16_t *c, uint32_t n) { gfx_clut_begin(start); for (uint32_t i = 0; i < n; i++) gfx_clut_put(c[i]); }

/* ---- the buffer the CPU draws into (Helios H2) -----------------------------------------------------------------------------------------------------------------
 * Plain rectangles and text follow R_DBUF_CPU in hardware. The blit-mode commands (BLIT, SBLIT, CBLIT) are addressed through the sticky SRC_BASE / DST_BASE fields instead, so every wrapper below sets them
 * from the buffer being drawn into (`cpu_buf`); the fields are write-only, so a shadow keeps what was last written and nothing is rewritten when it already holds the wanted pair. The stash rows
 * (palette planes, the tile plane, the background strip) are read through base 0: they are shared by both buffers. */
static uint8_t cpu_buf;
void gfx_fence(void);
static uint32_t base_src = 0xFFFFFFFFu, base_dst = 0xFFFFFFFFu;
static uint32_t buf_base(uint32_t b) { return b ? DBUF_BASE1_W : 0u; }
static void set_bases(uint32_t src, uint32_t dst)
{
    if (src == base_src && dst == base_dst) return;
    gfx_fence();                                       /* the fields are read when a command EXECUTES: whatever is queued must run against the old pair first */
    wait_fifo();
    REG_WR(R_BLT_IDX, 0u); REG_WR(R_BLT_DATA, src);
    REG_WR(R_BLT_IDX, 2u); REG_WR(R_BLT_DATA, dst);
    base_src = src; base_dst = dst;
}
static void blit_op(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h, uint32_t go, uint32_t src_base, uint32_t dst_base)
{
    if (!w || !h) return;
    uint32_t src = sy * GFX_STRIDE + sx;
    gt_note(&gfx_touch, dy, h);
    set_bases(src_base, dst_base);
    wait_fifo();
    REG_WR(R_FB_ADDR, dy * GFX_STRIDE + dx);
    REG_WR(R_FB_SIZE, (h << 9) | w);
    REG_WR(R_FB_COLOR, ((src >> 16) & 0x7u) | ((src & 0xFFFFu) << 16));      /* the source address rides in the colour register */
    color_shadow = 0xFFFFFFFFu;
    FB_GO(go);
}
void gfx_cblit(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_CBLIT, 0u, buf_base(cpu_buf)); }
void gfx_cblit_abs(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_CBLIT, 0u, 0u); }
void gfx_blit(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_BLIT, buf_base(cpu_buf), buf_base(cpu_buf)); }
void gfx_blit_to_stash(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_BLIT, buf_base(cpu_buf), 0u); }
void gfx_blit_stash(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_BLIT, 0u, buf_base(cpu_buf)); }
void gfx_blit_abs(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h) { blit_op(sx, sy, dx, dy, w, h, OP_BLIT, 0u, 0u); }
void gfx_sblit(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h, uint32_t scale)
{
    const uint32_t s = scale == 3u ? 3u : scale == 2u ? 2u : 0u;                                  /* the engine's scale field: 0 = 1x, 2 = 2x, 3 = 3x */
    blit_op(sx, sy, dx, dy, w, h, OP_SBLIT | (s << 10) | (s << 12), 0u, buf_base(cpu_buf));
}
uint32_t gfx_cur_buf(void) { return cpu_buf; }
uint32_t gfx_front_buf(void) { return caps_dbuf ? (REG_RD(R_DBUF_DISP) & 1u) : 0u; }
void gfx_set_target(uint32_t buf)
{
    if (!caps_dbuf) return;
    buf &= 1u; wait_fifo();
    REG_WR(R_DBUF_CPU, buf); cpu_buf = (uint8_t)buf;
}

/* ---- a redraw into the idle buffer, shown at the next vblank --------------------------------------------------------------------------------------------
 * begin: the idle buffer is brought up to date with the displayed one (a copy) and becomes the CPU's target (returns 0 and touches nothing when the bitstream has no H2 or a flip is still pending). end: every queued command has executed (a fence), the flip
 * is requested and awaited (about one frame), and the target goes back to the displayed buffer so incremental drawing after it lands where it is seen. */
static uint8_t hold_next, held;
void gfx_hold_next(void) { hold_next = 1; }
int gfx_held(void) { return held; }
int gfx_frame_begin(void)
{
    if (!caps_dbuf || held || (REG_RD(R_DBUF_DISP) & 2u)) return 0;
    const uint32_t front = REG_RD(R_DBUF_DISP) & 1u;
    gfx_set_target(front ^ 1u);
    for (uint32_t cx = 0; cx < GFX_W; cx += 120u) blit_op(cx, 0u, cx, 0u, 120u < GFX_W - cx ? 120u : GFX_W - cx, GFX_H, OP_BLIT, buf_base(front), buf_base(front ^ 1u));      /* the idle buffer starts as a copy of what is shown: a partial redraw is then complete */
    return 1;
}
void gfx_frame_end(int active)
{
    if (!active) return;
    gfx_fence();
    if (hold_next) { hold_next = 0; held = 1; gfx_set_target(REG_RD(R_DBUF_DISP) & 1u); return; }      /* the picture stays in the idle buffer for a crossfade (gfx_xfade_step) */
    REG_WR(R_DBUF_DISP, 1u);
    const uint32_t t0 = cycles();
    while ((REG_RD(R_DBUF_DISP) & 2u) && (uint32_t)(cycles() - t0) < CLK_HZ / 10u) { }
    gfx_set_target(REG_RD(R_DBUF_DISP) & 1u);
}
/* An off-screen compose: the figure is drawn into the idle buffer (where no beam can show a half-built picture) and then copied onto the displayed one with blits (about a millisecond for a meter box,
 * much faster than the beam). Returns 1 when composing is possible; the caller then draws, and ends with gfx_compose_present(). */
int gfx_compose_begin(uint32_t x, uint32_t y, uint32_t w, uint32_t h)
{
    if (!caps_dbuf || held || (REG_RD(R_DBUF_DISP) & 2u) || cpu_buf != (REG_RD(R_DBUF_DISP) & 1u)) return 0;
    const uint32_t front = cpu_buf;
    gfx_set_target(front ^ 1u);
    for (uint32_t cx = 0; cx < w; cx += 120u) { const uint32_t c = w - cx < 120u ? w - cx : 120u; blit_op(x + cx, y, x + cx, y, c, h, OP_BLIT, buf_base(front), buf_base(front ^ 1u)); }   /* the box starts as a copy of what is shown: a figure that draws nothing this time presents what is already there */
    return 1;
}
void gfx_compose_present(uint32_t x, uint32_t y, uint32_t w, uint32_t h)
{
    gfx_fence();                                                  /* everything drawn into the idle buffer has executed */
    const uint32_t back = cpu_buf, front = back ^ 1u;
    for (uint32_t cx = 0; cx < w; cx += 120u) { const uint32_t c = w - cx < 120u ? w - cx : 120u; blit_op(x + cx, y, x + cx, y, c, h, OP_BLIT, buf_base(back), buf_base(front)); }
    gfx_fence();
    gfx_set_target(front);
}

/* ---- alpha blend (Talos B5): dst = (src * a + dst * (256 - a)) >> 8 per channel, for OP_BLIT only -------------------------------------------------------------------------------
 * The blend state is sticky and is read when a command EXECUTES: it is switched on, the blends are issued, a fence waits for them, and only then is it switched off. No other OP_BLIT may run in between. */
uint32_t gfx_blend_state;                     /* 0 not probed, 1 ready, 2 not in this bitstream (a wrong answer), 3 the mailbox did not answer (retried) */
uint32_t gfx_blend_tries;
void gfx_blend_on(uint32_t a) { wait_fifo(); REG_WR(R_BLT_IDX, 5u); REG_WR(R_BLT_DATA, ((a & 0xFFu) << 8) | 1u); }
void gfx_blend_off(void) { gfx_fence(); REG_WR(R_BLT_IDX, 5u); REG_WR(R_BLT_DATA, 0u); }
int gfx_blend_ready(void)
{
    if (gfx_blend_state == 1u || gfx_blend_state == 2u) return gfx_blend_state == 1u;
    if (gfx_blend_tries >= 8u) return 0;                 /* a mailbox that never answers: stop asking */
    gfx_blend_tries++;
    gfx_blend_state = 3u;                                /* a failure of the mailbox is not an answer: the next call asks again */
    const uint32_t src = 1019u * GFX_STRIDE + 508u, dst = 1020u * GFX_STRIDE + 508u;     /* stash cells: white over black at a = 128 gives 0x7BEF where the blend exists, 0xFFFF (a plain copy) where it does not */
    uint32_t r = 0;
    if (gfx_mb_write(src, 0xFFFFFFFFu) || gfx_mb_write(dst, 0u)) return 0;
    gfx_blend_on(128u);
    blit_op(508u, 1019u, 508u, 1020u, 1u, 1u, OP_BLIT, 0u, 0u);
    gfx_blend_off();
    if (gfx_mb_read(dst, &r)) return 0;
    gfx_blend_state = ((r & 0xFFFFu) == 0x7BEFu || (r >> 16) == 0x7BEFu) ? 1u : 2u;
    return gfx_blend_state == 1u;
}
/* Blend the w x h box at (sx, sy) (stash rows, shared) over the box at (dx, dy) of the buffer being drawn into, source weight a, in chunks of at most 112 columns; the caller has turned blend on. */
void gfx_blend_blit(uint32_t sx, uint32_t sy, uint32_t dx, uint32_t dy, uint32_t w, uint32_t h)
{
    for (uint32_t cx = 0; cx < w; cx += 112u) { const uint32_t c = w - cx < 112u ? w - cx : 112u; blit_op(sx, sy, dx + cx, dy, c, h, OP_BLIT, 0u, buf_base(cpu_buf)); }
}

/* ---- a crossfade from the shown buffer to a picture held in the idle one -------------------------------------------------------------------------------------
 * gfx_hold_next() makes the next gfx_frame_end() keep the freshly drawn picture in the idle buffer instead of flipping to it. gfx_xfade_step(a) then moves every pixel of the shown buffer toward it by the source weight
 * a/256 (a hardware blend, about 2-3 ms for the screen); with a >= 256 it is a plain copy, so a schedule that ends with 256 ends exactly on the new picture. gfx_xfade_end() releases the hold. While held, no other
 * full redraw or compose may use the idle buffer (they are refused). */
void gfx_xfade_step(uint32_t a)
{
    if (!held) return;
    const uint32_t front = REG_RD(R_DBUF_DISP) & 1u, idle = front ^ 1u;
    if (a < 256u) gfx_blend_on(a);
    for (uint32_t cx = 0; cx < GFX_W; cx += 120u) blit_op(cx, 0u, cx, 0u, 120u < GFX_W - cx ? 120u : GFX_W - cx, GFX_H, OP_BLIT, buf_base(idle), buf_base(front));
    if (a < 256u) gfx_blend_off();
}
void gfx_xfade_end(void) { held = 0; }
